module TopModule (
    input  logic [2:0] in,
    output logic [1:0] out
);

    // out[0] = parity (odd number of 1's)
    assign out[0] = in[2] ^ in[1] ^ in[0];

    // out[1] = majority (count >= 2)
    assign out[1] = (in[2] & in[1]) | (in[1] & in[0]) | (in[2] & in[0]);

