module TopModule (
    input  clk,
    input  resetn,
    input  in,
    output out
);

    // 4-bit shift register storage
    logic [3:0] q;

    // Sequential logic: positive-edge-triggered, active-low synchronous reset
    always_ff @(posedge clk) begin
        if (!resetn)
            q <= 4'b0;
