Prob074_ece241_2014_q4.code:
module TopModule (
    input  wire clk,
    input  wire x,
    output wire z
);

    // Internal state register for the three flip-flops
    // q[0] corresponds to the XOR flip-flop
    // q[1] corresponds to the AND flip-flop
    // q[2] corresponds to the OR flip-flop
    reg [2:0] q;

    // Positive edge-triggered D flip-flops with feedback from gates
    always @(posedge clk) begin
        // XOR flip-flop: D input is x XOR its own output
        q[0] <= x ^ q[0];

        // AND flip-flop: D input is x AND complemented own output
        q[1] <= x & ~q[1];

        // OR flip-flop: D input is x OR complemented own output
        q[2] <= x | ~q[2];
    end

    // Three-input NOR gate: output z is NOR of all flip-flop outputs
    assign z = ~(q[0] | q[1] | q[2]);

    // Initialize flip-flops to zero as per specification
    initial begin
        q = 3'b000;
    end

endmodule

