        .x(x),
        .y(y),
        .z(a1)
    );

    // First B submodule: inputs tied to top-level x and y
    B u_b1 (
        .x(x),
        .y(y),
        .z(b1)
    );

    // Second A submodule: inputs tied to top-level x and y
    A u_a2 (
        .x(x),
        .y(y),
        .z(a2)
    );

    // Second B submodule: inputs tied to top-level x and y
    B u_b2 (
        .x(x),
        .y(y),
        .z(b2)
    );

    // OR gate: first A output OR first B output
    assign or_out = a1 | b1;

    // AND gate: second A output AND second B output
    assign and_out = a2 & b2;

    // XOR gate: OR output XOR AND output -> z
    assign z = or_out ^ and_out;

