Prob096_review2015_fsmseq.code:
module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    output logic start_shifting
);

// State encoding for the sequence detector: 1101
typedef enum logic [1:0] {
    S0 = 2'b00, // Initial state, no match
    S1 = 2'b01, // Matched '1'
    S2 = 2'b10, // Matched '11'
    S3 = 2'b11  // Matched '110'
} state_t;

state_t ps, ns; // present state, next state

// -------------------------------------------------------
// Combinational logic: determines the next state based on
// the current state and the input data bit.
// -------------------------------------------------------
always_comb begin
    case (ps)
        S0: begin
            if (data == 1'b1)
                ns = S1;
            else
                ns = S0;
        end
        S1: begin
            if (data == 1'b1)
                ns = S2;
            else
                ns = S0;
        end
        S2: begin
            if (data == 1'b0)
                ns = S3; // Matched '110'
            else
                ns = S2; // Input '1', stay in '11' state (handles '111')
        end
        S3: begin
            if (data == 1'b1) begin
                ns = S1; // Sequence '1101' detected. The last '1' can start a new sequence.
            end
            else
                ns = S0; // Input '0', sequence broken
        end
        default: ns = S0;
    endcase
end

// -------------------------------------------------------
// Sequential logic: state updates and output generation.
// Reset is active high and synchronous (posedge clk).
// start_shifting becomes 1 once the sequence is found and
// remains 1 until reset is asserted.
// -------------------------------------------------------
always_ff @(posedge clk) begin
    if (reset) begin
        ps     <= S0;
        start_shifting <= 1'b0;
    end
    else begin
        ps <= ns;
        // If we are in state S3 (matched '110') and the current
        // input bit is '1', the sequence '1101' is complete.
        if (ps == S3 && data == 1'b1) begin
            start_shifting <= 1'b1;
        end
        // Otherwise, start_shifting retains its previous value
        // (sticky behavior: set to 1 forever until reset).
    end
end

endmodule

Prob150_review2015_fsmonehot.code:
module TopModule (
    input  logic        d,
    input  logic        done_counting,
    input  logic        ack,
    input  logic [9:0]  state,
    output logic        B3_next,
    output logic        S_next,
    output logic        S1_next,
    output logic        Count_next,
    output logic        Wait_next,
    output logic        done,
    output logic        counting,
    output logic        shift_ena
);

// One-hot state decoding (matches specification encoding)
// S       = state[0]
// S1      = state[1]
// S11     = state[2]
// S110    = state[3]
// B0      = state[4]
// B1      = state[5]
// B2      = state[6]
// B3      = state[7]
// Count   = state[8]
// Wait    = state[9]

wire curS       = state[0];
wire curS1      = state[1];
wire curS11     = state[2];
wire curS110    = state[3];
wire curB0      = state[4];
wire curB1      = state[5];
wire curB2      = state[6];
wire curB3      = state[7];
wire curCount   = state[8];
wire curWait    = state[9];

// ---------- Next-state logic (by inspection) ----------
assign B3_next  = curB2;                     // B2 --> B3 always

assign S_next   = (curS       & ~d) |       // S     --d=0--> S
                  (curS1      & ~d) |       // S1    --d=0--> S
                  (curS110    & ~d) |       // S110  --d=0--> S
                  (curWait    & ack);        // Wait  --ack=1--> S

assign S1_next  = curS & d;                  // S     --d=1--> S1

assign Count_next = curB3;                   // B3    --> Count always

assign Wait_next = curCount & done_counting; // Count --done_counting=1--> Wait

// ---------- Output logic (Moore) ----------
assign shift_ena = curB0 | curB1 | curB2 | curB3;   // B0, B1, B2, B3

assign counting = curCount;                       // Count state

assign done     = curWait;                        // Wait state

endmodule

Prob120_fsm3s.code:
module TopModule (
    input logic clk,
    input logic reset,
    input logic in,
    output logic out
);

    // State encoding: A=00, B=01, C=10, D=11
    reg [1:0] state, next_state;

    // Combinational next-state logic
    always_comb begin
        case (state)
            2'b00: next_state = in ? 2'b01 : 2'b00; // State A
            2'b01: next_state = in ? 2'b01 : 2'b10; // State B
            2'b10: next_state = in ? 2'b11 : 2'b00; // State C
            2'b11: next_state = in ? 2'b01 : 2'b10; // State D
            default: next_state = 2'b00;
        endcase
    end

    // Sequential state update (synchronous active-high reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state <= 2'b00; // reset to state A
        else
            state <= next_state;
    end

    // Moore output: out is 1 only in state D
    assign out = (state == 2'b11) ? 1'b1 : 1'b0;

endmodule

